1	package cli
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"io"
10		"log/slog"
11		"os"
12		"path/filepath"
13		"runtime"
14		"sort"
15		"strings"
16	
17		"github.com/entireio/cli/cmd/entire/cli/agent/external"
18		"github.com/entireio/cli/cmd/entire/cli/logging"
19	)
20	
21	// Managed plugin storage. The kubectl-style dispatcher in plugin.go resolves
22	// `entire-<name>` binaries from $PATH, period. To let `entire plugin install`
23	// be additive rather than a parallel mechanism, this file provides:
24	//
25	//  1. PluginBinDir() — a per-user managed dir that main.go prepends to PATH
26	//     before the dispatcher runs. Anything dropped here (or symlinked here)
27	//     becomes invocable as `entire <name>` without the user fiddling with PATH.
28	//
29	//  2. PluginDataDir(name) — a per-plugin durable storage dir, passed to plugins
30	//     as ENTIRE_PLUGIN_DATA_DIR. Independent of where the binary itself lives
31	//     so plugins installed via PATH and via the managed dir get the same
32	//     contract.
33	//
34	// Honors ENTIRE_PLUGIN_DIR as a parent-dir override; falls back to
35	// XDG_DATA_HOME, then a platform default.
36	
37	const (
38		pluginEnvPluginDir      = "ENTIRE_PLUGIN_DIR"
39		pluginManagedBinSubdir  = "bin"
40		pluginManagedDataSubdir = "data"
41		pluginEnvPluginData     = "ENTIRE_PLUGIN_DATA_DIR"
42		// Path segments for the managed plugin tree. Kept as separate
43		// segments (rather than "entire/plugins") so filepath.Join produces
44		// platform-native separators on Windows.
45		pluginManagedTopDir = "entire"
46		pluginManagedSubDir = "plugins"
47	)
48	
49	// pluginParentDir returns the per-user directory that holds the managed
50	// plugin storage. Resolution, in order:
51	//
52	//  1. ENTIRE_PLUGIN_DIR (cross-platform override).
53	//  2. On Windows: LOCALAPPDATA if set, else ~\AppData\Local\entire\plugins.
54	//  3. On Unix: XDG_DATA_HOME if set, else ~/.local/share/entire/plugins.
55	//
56	// XDG_DATA_HOME is deliberately ignored on Windows even when set (e.g. in
57	// MSYS/Cygwin) — Windows users expect Windows conventions, and routing
58	// through XDG would produce a surprising location.
59	//
60	// os.UserHomeDir is called only when no env-var branch resolves, so a
61	// degenerate environment with $LOCALAPPDATA or $XDG_DATA_HOME but no home
62	// still returns a usable path.
63	func pluginParentDir() (string, error) {
64		// ENTIRE_PLUGIN_DIR must be absolute. A relative value would resolve
65		// against the user's CWD at startup — typically inside their repo —
66		// which is the wrong place for managed plugin storage. Reject loudly
67		// rather than silently falling through to the platform default, since
68		// a misconfigured override is almost certainly a user error worth
69		// surfacing.
70		if v := os.Getenv(pluginEnvPluginDir); v != "" {
71			if !filepath.IsAbs(v) {
72				return "", fmt.Errorf("%s must be an absolute path, got %q", pluginEnvPluginDir, v)
73			}
74			return v, nil
75		}
76		if runtime.GOOS == windowsGOOS {
77			if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
78				return filepath.Join(appData, pluginManagedTopDir, pluginManagedSubDir), nil
79			}
80			home, err := os.UserHomeDir()
81			if err != nil {
82				return "", fmt.Errorf("resolve home dir: %w", err)
83			}
84			return filepath.Join(home, "AppData", "Local", pluginManagedTopDir, pluginManagedSubDir), nil
85		}
86		if v := os.Getenv("XDG_DATA_HOME"); v != "" {
87			return filepath.Join(v, pluginManagedTopDir, pluginManagedSubDir), nil
88		}
89		home, err := os.UserHomeDir()
90		if err != nil {
91			return "", fmt.Errorf("resolve home dir: %w", err)
92		}
93		return filepath.Join(home, ".local", "share", pluginManagedTopDir, pluginManagedSubDir), nil
94	}
95	
96	// PluginBinDir returns the managed install directory. Binaries (or symlinks)
97	// placed here are auto-discovered by the kubectl-style dispatcher because
98	// main.go prepends this dir to PATH before MaybeRunPlugin runs.
99	func PluginBinDir() (string, error) {
100		parent, err := pluginParentDir()
101		if err != nil {
102			return "", err
103		}
104		return filepath.Join(parent, pluginManagedBinSubdir), nil
105	}
106	
107	// PluginDataDir returns the per-plugin data directory for the given bare name
108	// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
109	// the plugin's responsibility on first use.
110	//
111	// Returns an error for names the dispatcher would never invoke (empty,
112	// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
113	// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
114	// data subtree.
115	func PluginDataDir(name string) (string, error) {
116		if err := validatePluginName(name); err != nil {
117			return "", err
118		}
119		parent, err := pluginParentDir()
120		if err != nil {
121			return "", err
122		}
123		return filepath.Join(parent, pluginManagedDataSubdir, name), nil
124	}
125	
126	// validatePluginName mirrors the dispatcher's isPluginCandidate rules and
127	// returns a descriptive error for invalid names. Used by every entry point
128	// that takes a plugin name from outside the dispatcher (data dir resolution,
129	// managed-dir install).
130	func validatePluginName(name string) error {
131		if name == "" {
132			return errors.New("plugin name is empty")
133		}
134		if strings.HasPrefix(name, "-") {
135			return fmt.Errorf("plugin name %q must not start with '-'", name)
136		}
137		if strings.HasPrefix(name, "agent-") {
138			return fmt.Errorf("plugin name %q is reserved for the external agent protocol", name)
139		}
140		if strings.ContainsAny(name, `/\`) {
141			return fmt.Errorf("plugin name %q must not contain path separators", name)
142		}
143		if name == "." || name == ".." {
144			return fmt.Errorf("plugin name %q is not a valid identifier", name)
145		}
146		return nil
147	}
148	
149	// EnsurePluginBinDir creates the managed install dir if it doesn't exist.
150	func EnsurePluginBinDir() (string, error) {
151		dir, err := PluginBinDir()
152		if err != nil {
153			return "", err
154		}
155		if err := os.MkdirAll(dir, 0o750); err != nil {
156			return "", fmt.Errorf("create plugin bin dir: %w", err)
157		}
158		return dir, nil
159	}
160	
161	// PrependPluginBinDirToPATH prepends the managed bin dir to the process's
162	// PATH so the kubectl dispatcher discovers managed-installed plugins.
163	// Idempotent against an already-prepended dir.
164	//
165	// Returns a restore closure the caller invokes to revert PATH to its
166	// previous value. Restoring matters when no plugin runs: built-in commands
167	// and the subprocesses they spawn (git, hooks, less, …) should see the
168	// user's original PATH, not one with the managed plugin dir prepended.
169	// When a plugin *is* dispatched, callers can simply skip the restore — the
170	// process exits anyway, and the plugin child intentionally inherits the
171	// prepended PATH so it can spawn sibling managed plugins.
172	//
173	// Errors and no-op cases (already-prepended, lookup failure) return a
174	// no-op restore so callers always have a safe func to call. Failures are
175	// emitted at debug level — the surface symptom ("my managed plugin
176	// doesn't run") is otherwise silent and hard to diagnose; a debug log
177	// surfaces the cause for users who flip log_level=DEBUG.
178	func PrependPluginBinDirToPATH(ctx context.Context) func() {
179		dir, err := PluginBinDir()
180		if err != nil || dir == "" {
181			if err != nil {
182				logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: resolve failed", slog.String("error", err.Error()))
183			}
184			return func() {}
185		}
186		prev := os.Getenv("PATH")
187		sep := string(os.PathListSeparator)
188		if prev == "" {
189			if err := os.Setenv("PATH", dir); err != nil {
190				logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
191				return func() {}
192			}
193			return func() { _ = os.Setenv("PATH", "") }
194		}
195		// Idempotent: if the first entry already matches, leave PATH alone.
196		// Windows PATH lookups are case-insensitive (`C:\Foo` and `c:\foo`
197		// resolve identically), so a case-different first entry is the same
198		// dir and we should not double-prepend.
199		first := prev
200		if i := strings.Index(prev, sep); i >= 0 {
201			first = prev[:i]
202		}
203		if pathEntriesEqual(first, dir) {
204			return func() {}
205		}
206		if err := os.Setenv("PATH", dir+sep+prev); err != nil {
207			logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
208			return func() {}
209		}
210		return func() { _ = os.Setenv("PATH", prev) }
211	}
212	
213	// pathEntriesEqual reports whether two PATH entries refer to the same dir.
214	// filepath.Clean normalizes trailing separators and (on Windows) slash
215	// orientation; case folding handles Windows' case-insensitive lookup.
216	func pathEntriesEqual(a, b string) bool {
217		a = filepath.Clean(a)
218		b = filepath.Clean(b)
219		if runtime.GOOS == windowsGOOS {
220			return strings.EqualFold(a, b)
221		}
222		return a == b
223	}
224	
225	// InstalledPlugin describes a single entry in the managed bin dir.
226	type InstalledPlugin struct {
227		// Name is the bare plugin name (without the `entire-` prefix and any
228		// platform-specific extension).
229		Name string
230		// Path is the absolute path inside the managed bin dir.
231		Path string
232		// Symlink is true when Path is a symlink to a source location elsewhere
233		// (the typical local-dev install). LinkTarget is populated in that case.
234		Symlink    bool
235		LinkTarget string
236	}
237	
238	// ListInstalledPlugins enumerates entries in the managed bin dir whose name
239	// starts with `entire-`. Sorted by bare name. A missing dir returns no error
240	// and an empty slice.
241	func ListInstalledPlugins() ([]*InstalledPlugin, error) {
242		dir, err := PluginBinDir()
243		if err != nil {
244			return nil, err
245		}
246		entries, err := os.ReadDir(dir)
247		if err != nil {
248			if errors.Is(err, os.ErrNotExist) {
249				return nil, nil
250			}
251			return nil, fmt.Errorf("read plugin bin dir: %w", err)
252		}
253	
254		var out []*InstalledPlugin
255		for _, e := range entries {
256			full := e.Name()
257			if !strings.HasPrefix(full, pluginBinaryPrefix) {
258				continue
259			}
260			bare := bareNameFromBinaryName(full)
261			if bare == "" {
262				continue
263			}
264			path := filepath.Join(dir, full)
265			info, err := os.Lstat(path)
266			if err != nil {
267				continue
268			}
269			ip := &InstalledPlugin{Name: bare, Path: path}
270			if info.Mode()&os.ModeSymlink != 0 {
271				ip.Symlink = true
272				if target, err := os.Readlink(path); err == nil {
273					ip.LinkTarget = target
274				}
275			}
276			out = append(out, ip)
277		}
278		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
279		return out, nil
280	}
281	
282	// FindInstalledPlugin returns the entry for the given bare name, or nil if
283	// it isn't installed in the managed dir.
284	func FindInstalledPlugin(name string) (*InstalledPlugin, error) {
285		all, err := ListInstalledPlugins()
286		if err != nil {
287			return nil, err
288		}
289		for _, p := range all {
290			if p.Name == name {
291				return p, nil
292			}
293		}
294		return nil, nil //nolint:nilnil // not-installed signal
295	}
296	
297	// InstallPluginOptions configures InstallPluginFromPath.
298	type InstallPluginOptions struct {
299		// SourcePath is the absolute (or working-dir-relative) path to the plugin
300		// executable. Its basename — minus any platform extension — must match
301		// `entire-<name>` so the dispatcher can resolve it.
302		SourcePath string
303		// Force replaces an already-installed plugin with the same name.
304		Force bool
305	}
306	
307	// InstallPluginFromPath symlinks SourcePath into the managed bin dir. The
308	// caller is responsible for built-in conflict checks (resolvePlugin already
309	// gates dispatch on rootCmd.Find — installing a name that shadows a built-in
310	// is allowed but the built-in still wins at runtime).
311	//
312	// Refuses names the dispatcher will never invoke (agent-protocol prefix,
313	// flag-shaped, "."/"..", slashes), and refuses self-install when the source
314	// is the same file as the would-be managed entry. The replace step is
315	// atomic: a new symlink is created at <dest>.tmp and renamed onto <dest>,
316	// so a failed --force never leaves the previous install missing.
317	func InstallPluginFromPath(opts InstallPluginOptions) (*InstalledPlugin, error) {
318		src, err := filepath.Abs(opts.SourcePath)
319		if err != nil {
320			return nil, fmt.Errorf("resolve source path: %w", err)
321		}
322		srcInfo, err := os.Stat(src)
323		if err != nil {
324			return nil, fmt.Errorf("stat source: %w", err)
325		}
326		if srcInfo.IsDir() {
327			return nil, fmt.Errorf("source must be a file, got directory: %s", src)
328		}
329		base := filepath.Base(src)
330		bare := bareNameFromBinaryName(base)
331		if bare == "" {
332			return nil, fmt.Errorf("source basename %q must start with %q and have a runnable name", base, pluginBinaryPrefix)
333		}
334		if err := validatePluginName(bare); err != nil {
335			return nil, fmt.Errorf("derived plugin name from %q is not dispatchable: %w", base, err)
336		}
337		if runtime.GOOS != windowsGOOS && srcInfo.Mode()&0o111 == 0 {
338			return nil, fmt.Errorf("source %s is not executable (chmod +x)", src)
339		}
340	
341		binDir, err := EnsurePluginBinDir()
342		if err != nil {
343			return nil, err
344		}
345		dest := filepath.Join(binDir, base)
346	
347		// Reject self-install: the source path already equals the managed
348		// destination path. Without this guard, `--force` would atomically
349		// rename a tmp symlink onto its own target file and the underlying
350		// binary would be unlinked.
351		//
352		// We deliberately do NOT use os.SameFile here. The legitimate
353		// repeat-install case has dest as a symlink we created on a prior
354		// install; SameFile would resolve dest through the symlink to src
355		// and falsely trip. Path equality is the precise risky case.
356		if filepath.Clean(src) == filepath.Clean(dest) {
357			return nil, fmt.Errorf("source %s is already the managed entry; nothing to install", src)
358		}
359	
360		// Conflict check on the bare name (not the exact filename). On Windows,
361		// entire-foo.exe / .bat / .cmd all map to bare name "foo"; checking only
362		// the destination filename would let a second install of a different
363		// extension silently coexist with the first, with PATHEXT ordering then
364		// deciding which one runs. List all variants and require --force when
365		// any exist.
366		conflicts, err := installedVariantsByBareName(bare)
367		if err != nil {
368			return nil, err
369		}
370		if len(conflicts) > 0 && !opts.Force {
371			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", bare, conflicts[0].Path)
372		}
373		// With --force, remove every variant other than the one we're about to
374		// atomically overwrite. The same-extension case is handled by the
375		// rename below, which atomically replaces dest.
376		for _, c := range conflicts {
377			if filepath.Clean(c.Path) == filepath.Clean(dest) {
378				continue
379			}
380			if err := os.Remove(c.Path); err != nil && !errors.Is(err, os.ErrNotExist) {
381				return nil, fmt.Errorf("remove existing variant %s: %w", c.Path, err)
382			}
383		}
384	
385		// Atomic replace via tmp + rename. Rename is atomic on POSIX and
386		// replaces an existing target on Windows (Go's os.Rename uses
387		// MoveFileEx with MOVEFILE_REPLACE_EXISTING). If linking or rename
388		// fails, the previously installed plugin (if any) is unaffected.
389		//
390		// The tmp path uses a random suffix and a `.install-` prefix that does
391		// NOT match `entire-`. This protects against two distinct hazards:
392		//   1. A user can have a legitimate plugin named "foo.tmp" (file
393		//      "entire-foo.tmp"), which a naive `dest + ".tmp"` would clobber.
394		//   2. ListInstalledPlugins filters by `entire-` prefix, so a tmp that
395		//      starts with `.install-` will not appear in `entire plugin list`
396		//      while the install is in progress.
397		tmpDest, err := makeInstallTmpPath(binDir)
398		if err != nil {
399			return nil, err
400		}
401		if err := materializeManagedEntry(src, tmpDest, srcInfo); err != nil {
402			return nil, fmt.Errorf("install plugin: %w", err)
403		}
404		if err := os.Rename(tmpDest, dest); err != nil {
405			_ = os.Remove(tmpDest) // best-effort cleanup; previous install is intact
406			return nil, fmt.Errorf("install plugin: %w", err)
407		}
408		return FindInstalledPlugin(bare)
409	}
410	
411	// installedVariantsByBareName returns every managed entry whose bare name
412	// matches name. On Unix this is at most one entry; on Windows multiple
413	// extensions can map to the same bare name.
414	func installedVariantsByBareName(name string) ([]*InstalledPlugin, error) {
415		all, err := ListInstalledPlugins()
416		if err != nil {
417			return nil, err
418		}
419		var out []*InstalledPlugin
420		for _, p := range all {
421			if p.Name == name {
422				out = append(out, p)
423			}
424		}
425		return out, nil
426	}
427	
428	// makeInstallTmpPath returns a unique scratch path inside binDir for the
429	// in-progress install. The `.install-` prefix is deliberately distinct from
430	// pluginBinaryPrefix so ListInstalledPlugins ignores it; a 16-char hex
431	// suffix from crypto/rand makes collisions vanishingly unlikely and keeps
432	// concurrent installs safe from each other.
433	func makeInstallTmpPath(binDir string) (string, error) {
434		var b [8]byte
435		if _, err := rand.Read(b[:]); err != nil {
436			return "", fmt.Errorf("generate install tmp suffix: %w", err)
437		}
438		return filepath.Join(binDir, ".install-"+hex.EncodeToString(b[:])), nil
439	}
440	
441	// materializeManagedEntry creates dest as a reference to src, falling back
442	// through symlink → hardlink → copy in that order.
443	//
444	// Symlink-first preserves the dev-loop property that rebuilding the source
445	// is immediately reflected in the managed entry. The fallbacks exist for
446	// Windows: os.Symlink there requires Developer Mode or admin, and silently
447	// breaks `entire plugin install` for typical users without either. Mirrors
448	// the pattern in setup_test.go's copyExecutable.
449	//
450	// On a successful copy the file mode of the source is preserved so the
451	// executable bit survives.
452	func materializeManagedEntry(src, dest string, srcInfo os.FileInfo) error {
453		if err := os.Symlink(src, dest); err == nil {
454			return nil
455		}
456		if err := os.Link(src, dest); err == nil {
457			return nil
458		}
459		return copyFileStreaming(src, dest, srcInfo)
460	}
461	
462	// copyFileStreaming copies src to dest in fixed-size buffers, preserving the
463	// source's executable mode. Plugin binaries can be tens of megabytes; using
464	// io.Copy avoids the heap spike of reading the whole file into memory.
465	func copyFileStreaming(src, dest string, srcInfo os.FileInfo) error {
466		mode := srcInfo.Mode().Perm()
467		if mode == 0 {
468			mode = 0o755
469		}
470		in, err := os.Open(src) //nolint:gosec // src is the user-provided plugin executable; reading it is the point
471		if err != nil {
472			return fmt.Errorf("open source for copy fallback: %w", err)
473		}
474		defer in.Close()
475	
476		// G304: dest is always inside the managed bin dir. The basename comes
477		// from a validated plugin name (validatePluginName ran upstream), and
478		// the parent dir comes from EnsurePluginBinDir.
479		out, err := os.OpenFile(dest, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode) //nolint:gosec // dest is constrained to the managed bin dir
480		if err != nil {
481			return fmt.Errorf("open destination for copy fallback: %w", err)
482		}
483		if _, err := io.Copy(out, in); err != nil {
484			_ = out.Close()
485			_ = os.Remove(dest)
486			return fmt.Errorf("copy fallback: %w", err)
487		}
488		if err := out.Close(); err != nil {
489			_ = os.Remove(dest)
490			return fmt.Errorf("close destination after copy fallback: %w", err)
491		}
492		return nil
493	}
494	
495	// RemoveInstalledPlugin removes every managed-dir entry whose bare name
496	// matches name. Symlinks are unlinked without touching the source file.
497	//
498	// Iterating all variants matters on Windows, where entire-foo.exe,
499	// entire-foo.bat, and entire-foo.cmd all map to bare name "foo" and could
500	// otherwise leave a runnable variant behind after `entire plugin remove foo`.
501	// On Unix the loop typically runs once.
502	func RemoveInstalledPlugin(name string) error {
503		variants, err := installedVariantsByBareName(name)
504		if err != nil {
505			return err
506		}
507		if len(variants) == 0 {
508			return fmt.Errorf("plugin %q is not installed in the managed directory", name)
509		}
510		for _, p := range variants {
511			if err := os.Remove(p.Path); err != nil && !errors.Is(err, os.ErrNotExist) {
512				return fmt.Errorf("remove plugin entry %s: %w", p.Path, err)
513			}
514		}
515		return nil
516	}
517	
518	// bareNameFromBinaryName turns a plugin executable's basename into the bare
519	// name the dispatcher uses (e.g. "entire-pgr" → "pgr"). Returns "" if the
520	// input doesn't match the expected shape.
521	//
522	// Extension stripping is platform-conditional:
523	//
524	//   - On Windows, .exe/.bat/.cmd are the natural extensions for executables
525	//     and exec.LookPath resolves them via PATHEXT, so we strip them so the
526	//     bare name a user types ("pgr") matches both the managed-list display
527	//     and the dispatcher's lookup.
528	//
529	//   - On Unix, exec.LookPath matches the exact filename. If we stripped here,
530	//     "entire-pgr.exe" would be listed as "pgr" and the user would type
531	//     "entire pgr", but the dispatcher's exec.LookPath("entire-pgr") would
532	//     not find "entire-pgr.exe". Leaving the dot in place keeps the listed
533	//     name aligned with the only invocation that actually resolves
534	//     ("entire pgr.exe"), avoiding silent shadowing surprises.
535	func bareNameFromBinaryName(base string) string {
536		if !strings.HasPrefix(base, pluginBinaryPrefix) {
537			return ""
538		}
539		cleaned := base
540		if runtime.GOOS == windowsGOOS {
541			// Reuse the canonical Windows-executable-extension list from
542			// agent/external rather than maintaining a parallel copy. plugin.go
543			// already depends on this package for isAgentProtocolBinary, so
544			// there's no new layering cost.
545			cleaned = external.StripExeExt(base)
546		}
547		bare := strings.TrimPrefix(cleaned, pluginBinaryPrefix)
548		if bare == "" {
549			return ""
550		}
551		return bare
552	}
553

