package cli

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Managed plugin storage. The kubectl-style dispatcher in plugin.go resolves
// `entire-<name>` binaries from $PATH, period. To let `entire plugin install`
// be additive rather than a parallel mechanism, this file provides:
//
//  1. PluginBinDir() — a per-user managed dir that main.go prepends to PATH
//     before the dispatcher runs. Anything dropped here (or symlinked here)
//     becomes invocable as `entire <name>` without the user fiddling with PATH.
//
//  2. PluginDataDir(name) — a per-plugin durable storage dir, passed to plugins
//     as ENTIRE_PLUGIN_DATA_DIR. Independent of where the binary itself lives
//     so plugins installed via PATH and via the managed dir get the same
//     contract.
//
// Honors ENTIRE_PLUGIN_DIR as a parent-dir override; falls back to
// XDG_DATA_HOME, then a platform default.

const (
	pluginEnvPluginDir      = "ENTIRE_PLUGIN_DIR"
	pluginManagedBinSubdir  = "bin"
	pluginManagedDataSubdir = "data"
	pluginEnvPluginData     = "ENTIRE_PLUGIN_DATA_DIR"
	// Path segments for the managed plugin tree. Kept as separate
	// segments (rather than "entire/plugins") so filepath.Join produces
	// platform-native separators on Windows.
	pluginManagedTopDir = "entire"
	pluginManagedSubDir = "plugins"
)

// pluginParentDir returns the per-user directory that holds the managed
// plugin storage. Resolution, in order:
//
//  1. ENTIRE_PLUGIN_DIR (cross-platform override).
//  2. On Windows: LOCALAPPDATA if set, else ~\AppData\Local\entire\plugins.
//  3. On Unix: XDG_DATA_HOME if set, else ~/.local/share/entire/plugins.
//
// XDG_DATA_HOME is deliberately ignored on Windows even when set (e.g. in
// MSYS/Cygwin) — Windows users expect Windows conventions, and routing
// through XDG would produce a surprising location.
//
// os.UserHomeDir is called only when no env-var branch resolves, so a
// degenerate environment with $LOCALAPPDATA or $XDG_DATA_HOME but no home
// still returns a usable path.
func pluginParentDir() (string, error) {
	// ENTIRE_PLUGIN_DIR must be absolute. A relative value would resolve
	// against the user's CWD at startup — typically inside their repo —
	// which is the wrong place for managed plugin storage. Reject loudly
	// rather than silently falling through to the platform default, since
	// a misconfigured override is almost certainly a user error worth
	// surfacing.
	if v := os.Getenv(pluginEnvPluginDir); v != "" {
		if !filepath.IsAbs(v) {
			return "", fmt.Errorf("%s must be an absolute path, got %q", pluginEnvPluginDir, v)
		}
		return v, nil
	}
	if runtime.GOOS == windowsGOOS {
		if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
			return filepath.Join(appData, pluginManagedTopDir, pluginManagedSubDir), nil
		}
		home, err := os.UserHomeDir()
		if err != nil {
			return "", fmt.Errorf("resolve home dir: %w", err)
		}
		return filepath.Join(home, "AppData", "Local", pluginManagedTopDir, pluginManagedSubDir), nil
	}
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		return filepath.Join(v, pluginManagedTopDir, pluginManagedSubDir), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve home dir: %w", err)
	}
	return filepath.Join(home, ".local", "share", pluginManagedTopDir, pluginManagedSubDir), nil
}

// PluginBinDir returns the managed install directory. Binaries (or symlinks)
// placed here are auto-discovered by the kubectl-style dispatcher because
// main.go prepends this dir to PATH before MaybeRunPlugin runs.
func PluginBinDir() (string, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedBinSubdir), nil
}

// PluginDataDir returns the per-plugin data directory for the given bare name
// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
// the plugin's responsibility on first use.
//
// Returns an error for names the dispatcher would never invoke (empty,
// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
// data subtree.
func PluginDataDir(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedDataSubdir, name), nil
}

// validatePluginName mirrors the dispatcher's isPluginCandidate rules and
// returns a descriptive error for invalid names. Used by every entry point
// that takes a plugin name from outside the dispatcher (data dir resolution,
// managed-dir install).
func validatePluginName(name string) error {
	if name == "" {
		return errors.New("plugin name is empty")
	}
	if strings.HasPrefix(name, "-") {
		return fmt.Errorf("plugin name %q must not start with '-'", name)
	}
	if strings.HasPrefix(name, "agent-") {
		return fmt.Errorf("plugin name %q is reserved for the external agent protocol", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("plugin name %q must not contain path separators", name)
	}
	if name == "." || name == ".." {
		return fmt.Errorf("plugin name %q is not a valid identifier", name)
	}
	return nil
}

// EnsurePluginBinDir creates the managed install dir if it doesn't exist.
func EnsurePluginBinDir() (string, error) {
	dir, err := PluginBinDir()
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return "", fmt.Errorf("create plugin bin dir: %w", err)
	}
	return dir, nil
}

// PrependPluginBinDirToPATH prepends the managed bin dir to the process's
// PATH so the kubectl dispatcher discovers managed-installed plugins.
// Idempotent against an already-prepended dir.
//
// Returns a restore closure the caller invokes to revert PATH to its
// previous value. Restoring matters when no plugin runs: built-in commands
// and the subprocesses they spawn (git, hooks, less, …) should see the
// user's original PATH, not one with the managed plugin dir prepended.
// When a plugin *is* dispatched, callers can simply skip the restore — the
// process exits anyway, and the plugin child intentionally inherits the
// prepended PATH so it can spawn sibling managed plugins.
//
// Errors and no-op cases (already-prepended, lookup failure) return a
// no-op restore so callers always have a safe func to call. Failures are
// emitted at debug level — the surface symptom ("my managed plugin
// doesn't run") is otherwise silent and hard to diagnose; a debug log
// surfaces the cause for users who flip log_level=DEBUG.
func PrependPluginBinDirToPATH(ctx context.Context) func() {
	dir, err := PluginBinDir()
	if err != nil || dir == "" {
		if err != nil {
			logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: resolve failed", slog.String("error", err.Error()))
		}
		return func() {}
	}
	prev := os.Getenv("PATH")
	sep := string(os.PathListSeparator)
	if prev == "" {
		if err := os.Setenv("PATH", dir); err != nil {
			logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
			return func() {}
		}
		return func() { _ = os.Setenv("PATH", "") }
	}
	// Idempotent: if the first entry already matches, leave PATH alone.
	// Windows PATH lookups are case-insensitive (`C:\Foo` and `c:\foo`
	// resolve identically), so a case-different first entry is the same
	// dir and we should not double-prepend.
	first := prev
	if i := strings.Index(prev, sep); i >= 0 {
		first = prev[:i]
	}
	if pathEntriesEqual(first, dir) {
		return func() {}
	}
	if err := os.Setenv("PATH", dir+sep+prev); err != nil {
		logging.Debug(ctx, "skip prepend managed plugin bin dir to PATH: setenv failed", slog.String("error", err.Error()))
		return func() {}
	}
	return func() { _ = os.Setenv("PATH", prev) }
}

// pathEntriesEqual reports whether two PATH entries refer to the same dir.
// filepath.Clean normalizes trailing separators and (on Windows) slash
// orientation; case folding handles Windows' case-insensitive lookup.
func pathEntriesEqual(a, b string) bool {
	a = filepath.Clean(a)
	b = filepath.Clean(b)
	if runtime.GOOS == windowsGOOS {
		return strings.EqualFold(a, b)
	}
	return a == b
}

// InstalledPlugin describes a single entry in the managed bin dir.
type InstalledPlugin struct {
	// Name is the bare plugin name (without the `entire-` prefix and any
	// platform-specific extension).
	Name string
	// Path is the absolute path inside the managed bin dir.
	Path string
	// Symlink is true when Path is a symlink to a source location elsewhere
	// (the typical local-dev install). LinkTarget is populated in that case.
	Symlink    bool
	LinkTarget string
}

// ListInstalledPlugins enumerates entries in the managed bin dir whose name
// starts with `entire-`. Sorted by bare name. A missing dir returns no error
// and an empty slice.
func ListInstalledPlugins() ([]*InstalledPlugin, error) {
	dir, err := PluginBinDir()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read plugin bin dir: %w", err)
	}

	var out []*InstalledPlugin
	for _, e := range entries {
		full := e.Name()
		if !strings.HasPrefix(full, pluginBinaryPrefix) {
			continue
		}
		bare := bareNameFromBinaryName(full)
		if bare == "" {
			continue
		}
		path := filepath.Join(dir, full)
		info, err := os.Lstat(path)
		if err != nil {
			continue
		}
		ip := &InstalledPlugin{Name: bare, Path: path}
		if info.Mode()&os.ModeSymlink != 0 {
			ip.Symlink = true
			if target, err := os.Readlink(path); err == nil {
				ip.LinkTarget = target
			}
		}
		out = append(out, ip)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// FindInstalledPlugin returns the entry for the given bare name, or nil if
// it isn't installed in the managed dir.
func FindInstalledPlugin(name string) (*InstalledPlugin, error) {
	all, err := ListInstalledPlugins()
	if err != nil {
		return nil, err
	}
	for _, p := range all {
		if p.Name == name {
			return p, nil
		}
	}
	return nil, nil //nolint:nilnil // not-installed signal
}

// InstallPluginOptions configures InstallPluginFromPath.
type InstallPluginOptions struct {
	// SourcePath is the absolute (or working-dir-relative) path to the plugin
	// executable. Its basename — minus any platform extension — must match
	// `entire-<name>` so the dispatcher can resolve it.
	SourcePath string
	// Force replaces an already-installed plugin with the same name.
	Force bool
}

// InstallPluginFromPath symlinks SourcePath into the managed bin dir. The
// caller is responsible for built-in conflict checks (resolvePlugin already
// gates dispatch on rootCmd.Find — installing a name that shadows a built-in
// is allowed but the built-in still wins at runtime).
//
// Refuses names the dispatcher will never invoke (agent-protocol prefix,
// flag-shaped, "."/"..", slashes), and refuses self-install when the source
// is the same file as the would-be managed entry. The replace step is
// atomic: a new symlink is created at <dest>.tmp and renamed onto <dest>,
// so a failed --force never leaves the previous install missing.
func InstallPluginFromPath(opts InstallPluginOptions) (*InstalledPlugin, error) {
	src, err := filepath.Abs(opts.SourcePath)
	if err != nil {
		return nil, fmt.Errorf("resolve source path: %w", err)
	}
	srcInfo, err := os.Stat(src)
	if err != nil {
		return nil, fmt.Errorf("stat source: %w", err)
	}
	if srcInfo.IsDir() {
		return nil, fmt.Errorf("source must be a file, got directory: %s", src)
	}
	base := filepath.Base(src)
	bare := bareNameFromBinaryName(base)
	if bare == "" {
		return nil, fmt.Errorf("source basename %q must start with %q and have a runnable name", base, pluginBinaryPrefix)
	}
	if err := validatePluginName(bare); err != nil {
		return nil, fmt.Errorf("derived plugin name from %q is not dispatchable: %w", base, err)
	}
	if runtime.GOOS != windowsGOOS && srcInfo.Mode()&0o111 == 0 {
		return nil, fmt.Errorf("source %s is not executable (chmod +x)", src)
	}

	binDir, err := EnsurePluginBinDir()
	if err != nil {
		return nil, err
	}
	dest := filepath.Join(binDir, base)

	// Reject self-install: the source path already equals the managed
	// destination path. Without this guard, `--force` would atomically
	// rename a tmp symlink onto its own target file and the underlying
	// binary would be unlinked.
	//
	// We deliberately do NOT use os.SameFile here. The legitimate
	// repeat-install case has dest as a symlink we created on a prior
	// install; SameFile would resolve dest through the symlink to src
	// and falsely trip. Path equality is the precise risky case.
	if filepath.Clean(src) == filepath.Clean(dest) {
		return nil, fmt.Errorf("source %s is already the managed entry; nothing to install", src)
	}

	// Conflict check on the bare name (not the exact filename). On Windows,
	// entire-foo.exe / .bat / .cmd all map to bare name "foo"; checking only
	// the destination filename would let a second install of a different
	// extension silently coexist with the first, with PATHEXT ordering then
	// deciding which one runs. List all variants and require --force when
	// any exist.
	conflicts, err := installedVariantsByBareName(bare)
	if err != nil {
		return nil, err
	}
	if len(conflicts) > 0 && !opts.Force {
		return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", bare, conflicts[0].Path)
	}
	// With --force, remove every variant other than the one we're about to
	// atomically overwrite. The same-extension case is handled by the
	// rename below, which atomically replaces dest.
	for _, c := range conflicts {
		if filepath.Clean(c.Path) == filepath.Clean(dest) {
			continue
		}
		if err := os.Remove(c.Path); err != nil && !errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("remove existing variant %s: %w", c.Path, err)
		}
	}

	// Atomic replace via tmp + rename. Rename is atomic on POSIX and
	// replaces an existing target on Windows (Go's os.Rename uses
	// MoveFileEx with MOVEFILE_REPLACE_EXISTING). If linking or rename
	// fails, the previously installed plugin (if any) is unaffected.
	//
	// The tmp path uses a random suffix and a `.install-` prefix that does
	// NOT match `entire-`. This protects against two distinct hazards:
	//   1. A user can have a legitimate plugin named "foo.tmp" (file
	//      "entire-foo.tmp"), which a naive `dest + ".tmp"` would clobber.
	//   2. ListInstalledPlugins filters by `entire-` prefix, so a tmp that
	//      starts with `.install-` will not appear in `entire plugin list`
	//      while the install is in progress.
	tmpDest, err := makeInstallTmpPath(binDir)
	if err != nil {
		return nil, err
	}
	if err := materializeManagedEntry(src, tmpDest, srcInfo); err != nil {
		return nil, fmt.Errorf("install plugin: %w", err)
	}
	if err := os.Rename(tmpDest, dest); err != nil {
		_ = os.Remove(tmpDest) // best-effort cleanup; previous install is intact
		return nil, fmt.Errorf("install plugin: %w", err)
	}
	return FindInstalledPlugin(bare)
}

// installedVariantsByBareName returns every managed entry whose bare name
// matches name. On Unix this is at most one entry; on Windows multiple
// extensions can map to the same bare name.
func installedVariantsByBareName(name string) ([]*InstalledPlugin, error) {
	all, err := ListInstalledPlugins()
	if err != nil {
		return nil, err
	}
	var out []*InstalledPlugin
	for _, p := range all {
		if p.Name == name {
			out = append(out, p)
		}
	}
	return out, nil
}

// makeInstallTmpPath returns a unique scratch path inside binDir for the
// in-progress install. The `.install-` prefix is deliberately distinct from
// pluginBinaryPrefix so ListInstalledPlugins ignores it; a 16-char hex
// suffix from crypto/rand makes collisions vanishingly unlikely and keeps
// concurrent installs safe from each other.
func makeInstallTmpPath(binDir string) (string, error) {
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("generate install tmp suffix: %w", err)
	}
	return filepath.Join(binDir, ".install-"+hex.EncodeToString(b[:])), nil
}

// materializeManagedEntry creates dest as a reference to src, falling back
// through symlink → hardlink → copy in that order.
//
// Symlink-first preserves the dev-loop property that rebuilding the source
// is immediately reflected in the managed entry. The fallbacks exist for
// Windows: os.Symlink there requires Developer Mode or admin, and silently
// breaks `entire plugin install` for typical users without either. Mirrors
// the pattern in setup_test.go's copyExecutable.
//
// On a successful copy the file mode of the source is preserved so the
// executable bit survives.
func materializeManagedEntry(src, dest string, srcInfo os.FileInfo) error {
	if err := os.Symlink(src, dest); err == nil {
		return nil
	}
	if err := os.Link(src, dest); err == nil {
		return nil
	}
	return copyFileStreaming(src, dest, srcInfo)
}

// copyFileStreaming copies src to dest in fixed-size buffers, preserving the
// source's executable mode. Plugin binaries can be tens of megabytes; using
// io.Copy avoids the heap spike of reading the whole file into memory.
func copyFileStreaming(src, dest string, srcInfo os.FileInfo) error {
	mode := srcInfo.Mode().Perm()
	if mode == 0 {
		mode = 0o755
	}
	in, err := os.Open(src) //nolint:gosec // src is the user-provided plugin executable; reading it is the point
	if err != nil {
		return fmt.Errorf("open source for copy fallback: %w", err)
	}
	defer in.Close()

	// G304: dest is always inside the managed bin dir. The basename comes
	// from a validated plugin name (validatePluginName ran upstream), and
	// the parent dir comes from EnsurePluginBinDir.
	out, err := os.OpenFile(dest, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode) //nolint:gosec // dest is constrained to the managed bin dir
	if err != nil {
		return fmt.Errorf("open destination for copy fallback: %w", err)
	}
	if _, err := io.Copy(out, in); err != nil {
		_ = out.Close()
		_ = os.Remove(dest)
		return fmt.Errorf("copy fallback: %w", err)
	}
	if err := out.Close(); err != nil {
		_ = os.Remove(dest)
		return fmt.Errorf("close destination after copy fallback: %w", err)
	}
	return nil
}

// RemoveInstalledPlugin removes every managed-dir entry whose bare name
// matches name. Symlinks are unlinked without touching the source file.
//
// Iterating all variants matters on Windows, where entire-foo.exe,
// entire-foo.bat, and entire-foo.cmd all map to bare name "foo" and could
// otherwise leave a runnable variant behind after `entire plugin remove foo`.
// On Unix the loop typically runs once.
func RemoveInstalledPlugin(name string) error {
	variants, err := installedVariantsByBareName(name)
	if err != nil {
		return err
	}
	if len(variants) == 0 {
		return fmt.Errorf("plugin %q is not installed in the managed directory", name)
	}
	for _, p := range variants {
		if err := os.Remove(p.Path); err != nil && !errors.Is(err, os.ErrNotExist) {
			return fmt.Errorf("remove plugin entry %s: %w", p.Path, err)
		}
	}
	return nil
}

// bareNameFromBinaryName turns a plugin executable's basename into the bare
// name the dispatcher uses (e.g. "entire-pgr" → "pgr"). Returns "" if the
// input doesn't match the expected shape.
//
// Extension stripping is platform-conditional:
//
//   - On Windows, .exe/.bat/.cmd are the natural extensions for executables
//     and exec.LookPath resolves them via PATHEXT, so we strip them so the
//     bare name a user types ("pgr") matches both the managed-list display
//     and the dispatcher's lookup.
//
//   - On Unix, exec.LookPath matches the exact filename. If we stripped here,
//     "entire-pgr.exe" would be listed as "pgr" and the user would type
//     "entire pgr", but the dispatcher's exec.LookPath("entire-pgr") would
//     not find "entire-pgr.exe". Leaving the dot in place keeps the listed
//     name aligned with the only invocation that actually resolves
//     ("entire pgr.exe"), avoiding silent shadowing surprises.
func bareNameFromBinaryName(base string) string {
	if !strings.HasPrefix(base, pluginBinaryPrefix) {
		return ""
	}
	cleaned := base
	if runtime.GOOS == windowsGOOS {
		// Reuse the canonical Windows-executable-extension list from
		// agent/external rather than maintaining a parallel copy. plugin.go
		// already depends on this package for isAgentProtocolBinary, so
		// there's no new layering cost.
		cleaned = external.StripExeExt(base)
	}
	bare := strings.TrimPrefix(cleaned, pluginBinaryPrefix)
	if bare == "" {
		return ""
	}
	return bare
}

// Package settings provides configuration loading for Entire.
// This package is separate from cli to allow strategy package to import it
// without creating an import cycle (cli imports strategy).
package settings

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

const (
	// EntireSettingsFile is the path to the Entire settings file
	EntireSettingsFile = ".entire/settings.json"
	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
	EntireSettingsLocalFile = ".entire/settings.local.json"
	// ClonePreferencesFile is the path inside the git common dir for clone-local preferences.
	ClonePreferencesFile = "entire/preferences.json"
)

type worktreeRootContextKey struct{}

// WithWorktreeRoot returns a context that makes settings.Load resolve project
// and clone-local settings relative to worktreeRoot instead of the process cwd.
func WithWorktreeRoot(ctx context.Context, worktreeRoot string) context.Context {
	if worktreeRoot == "" {
		return ctx
	}
	return context.WithValue(ctx, worktreeRootContextKey{}, filepath.Clean(worktreeRoot))
}

func worktreeRootFromContext(ctx context.Context) (string, bool) {
	root, ok := ctx.Value(worktreeRootContextKey{}).(string)
	return root, ok && root != ""
}

// Commit linking mode constants.
const (
	// CommitLinkingAlways auto-links commits to sessions without prompting.
	CommitLinkingAlways = "always"
	// CommitLinkingPrompt prompts the user on each commit (default for existing users).
	CommitLinkingPrompt = "prompt"
)

// EntireSettings represents the .entire/settings.json configuration
type EntireSettings struct {
	// Enabled indicates whether Entire is active. When false, CLI commands
	// show a disabled message and hooks exit silently. Defaults to true.
	Enabled bool `json:"enabled"`

	// LocalDev indicates whether to use "go run" instead of the "entire" binary
	// This is used for development when the binary is not installed
	LocalDev bool `json:"local_dev,omitempty"`

	// LogLevel sets the logging verbosity (debug, info, warn, error).
	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
	// Defaults to "info".
	LogLevel string `json:"log_level,omitempty"`

	// StrategyOptions contains strategy-specific configuration
	StrategyOptions map[string]any `json:"strategy_options,omitempty"`

	// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
	// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
	// that don't source shell profiles and can't find "entire" on PATH.
	AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`

	// Telemetry controls anonymous usage analytics.
	// nil = not asked yet (show prompt), true = opted in, false = opted out
	Telemetry *bool `json:"telemetry,omitempty"`

	// Redaction configures PII redaction behavior for transcripts and metadata.
	Redaction *RedactionSettings `json:"redaction,omitempty"`

	// Review maps agent name (e.g. "claude-code") to the review config for
	// that agent. When empty, `entire review` triggers the first-run picker.
	Review map[string]ReviewConfig `json:"review,omitempty"`

	// ReviewFixAgent is the default agent used when applying aggregate or
	// multi-agent review findings with `entire review --fix`.
	ReviewFixAgent string `json:"review_fix_agent,omitempty"`

	// Investigate holds configuration for `entire investigate`. Empty means
	// `entire investigate` triggers the first-run picker.
	Investigate *InvestigateConfig `json:"investigate,omitempty"`

	// CommitLinking controls how commits are linked to agent sessions.
	// "always" = auto-link without prompting, "prompt" = ask on each commit.
	// Defaults to "prompt" (preserves existing user behavior).
	CommitLinking string `json:"commit_linking,omitempty"`

	// ExternalAgents enables discovery and registration of external agent
	// plugins (entire-agent-* binaries on $PATH). Defaults to false.
	ExternalAgents bool `json:"external_agents,omitempty"`

	// SummaryGeneration stores provider preferences for explain --generate.
	// This is separate from strategy_options.summarize, which controls
	// checkpoint auto-summarize behavior.
	SummaryGeneration *SummaryGenerationSettings `json:"summary_generation,omitempty"`

	// Vercel indicates that the repository uses Vercel and the metadata branch
	// should include a vercel.json that disables deployments for Entire branches.
	Vercel bool `json:"vercel,omitempty"`

	// SummaryTimeoutSeconds is an optional hard deadline (in seconds) for
	// `entire explain --generate` summary generation. Zero or negative means
	// "unset" -- falls back to the per-run --summary-timeout-seconds flag
	// (if set) or the package default (5 minutes). Raise for very large
	// transcripts; lower (e.g. 30) for fast-fail in CI.
	SummaryTimeoutSeconds int `json:"summary_timeout_seconds,omitempty"`

	// SignCheckpointCommits controls whether checkpoint commits are signed.
	// nil/true = sign (default), false = skip signing.
	SignCheckpointCommits *bool `json:"sign_checkpoint_commits,omitempty"`

	// Deprecated: no longer used. Exists to tolerate old settings files
	// that still contain "strategy": "auto-commit" or similar.
	Strategy string `json:"strategy,omitempty"`
}

// ClonePreferences stores clone-local, uncommitted preferences that should be
// shared by linked worktrees in the same git clone.
//
// Stored in the git common dir (not the worktree) so multiple worktrees of the
// same clone see the same preferences. Not committed because the file lives
// inside .git/.
type ClonePreferences struct {
	Review         map[string]ReviewConfig `json:"review,omitempty"`
	ReviewFixAgent string                  `json:"review_fix_agent,omitempty"`

	// ReviewMigrationDismissed records that the user declined the one-shot
	// migration of review keys from project settings to clone-local prefs.
	// Once true, `entire review` stops prompting on every invocation; the
	// user can re-enable by editing this file or deleting the key.
	ReviewMigrationDismissed bool `json:"review_migration_dismissed,omitempty"`
}

// SummaryGenerationSettings configures provider selection for on-demand
// checkpoint summaries generated by explain --generate.
type SummaryGenerationSettings struct {
	// Provider is the selected summary provider agent name
	// (for example "claude-code", "codex", or "gemini").
	Provider string `json:"provider,omitempty"`

	// Model is an optional model hint passed to the selected provider.
	Model string `json:"model,omitempty"`
}

// Validate returns an error if the settings combination is semantically invalid.
// A model without a provider is meaningless: the model hint needs a provider to
// route to. The load path calls Validate() after merging, catching hand-edited
// files that land in this state.
func (s *SummaryGenerationSettings) Validate() error {
	if s == nil {
		return nil
	}
	if s.Model != "" && s.Provider == "" {
		return fmt.Errorf("summary_generation.model %q set without summary_generation.provider", s.Model)
	}
	return nil
}

// SetProvider updates the provider and optionally the model, clearing any stale
// model from the previous provider when switching without a replacement.
// An empty newProvider preserves the current provider; an empty newModel
// preserves the current model unless the provider is changing, in which case
// the old model is cleared to avoid passing (say) a Claude model to Codex.
func (s *SummaryGenerationSettings) SetProvider(newProvider, newModel string) {
	if s == nil {
		return
	}
	if newProvider != "" && s.Provider != "" && s.Provider != newProvider && newModel == "" {
		s.Model = ""
	}
	if newProvider != "" {
		s.Provider = newProvider
	}
	if newModel != "" {
		s.Model = newModel
	}
}

// RedactionSettings configures redaction behavior beyond the default secret detection.
type RedactionSettings struct {
	PII *PIISettings `json:"pii,omitempty"`

	// CustomRedactions is a label → RE2 regex map for user-defined patterns
	// to scrub from transcripts. Use it for internal credential shapes the
	// bundled detectors don't know about, project codenames, or any other
	// string pattern you don't want stored. Each match is replaced with the
	// bare "REDACTED" token used by the built-in secret layers, not the
	// "[REDACTED_<LABEL>]" token used by PII. Failed regex compilations are
	// logged via slog.Warn and the rule is skipped.
	CustomRedactions map[string]string `json:"custom_redactions,omitempty"`
}

// PIISettings configures PII detection categories.
// When Enabled is true, email and phone default to true; address defaults to false.
type PIISettings struct {
	Enabled        bool              `json:"enabled"`
	Email          *bool             `json:"email,omitempty"`
	Phone          *bool             `json:"phone,omitempty"`
	Address        *bool             `json:"address,omitempty"`
	CustomPatterns map[string]string `json:"custom_patterns,omitempty"`
}

// GetCommitLinking returns the effective commit linking mode.
// Returns the explicit value if set, otherwise defaults to "prompt"
// to preserve existing user behavior.
func (s *EntireSettings) GetCommitLinking() string {
	if s.CommitLinking != "" {
		return s.CommitLinking
	}
	return CommitLinkingPrompt
}

// SummaryTimeoutValue returns the configured hard deadline for
// `entire explain --generate` summary generation. Zero means "unset" --
// the caller picks the default. Negative values are treated as unset.
func (s *EntireSettings) SummaryTimeoutValue() time.Duration {
	if s.SummaryTimeoutSeconds < 1 {
		return 0
	}
	return time.Duration(s.SummaryTimeoutSeconds) * time.Second
}

// ReviewConfig holds the per-agent review configuration. Both fields are
// optional; together they describe what `entire review` should ask the
// agent to do.
//
// Precedence when composing the review prompt sent to the agent:
//   - If Prompt is non-empty, it is used verbatim.
//   - Otherwise, Skills are composed into a default template
//     ("Please run these review skills in order: 1. /X 2. /Y").
//
// Skills are always recorded on the checkpoint metadata regardless of
// which path composed the prompt — they're the structured, queryable
// tag alongside ReviewPrompt (which is the ground truth).
type ReviewConfig struct {
	// Skills is the list of slash-prefixed skill invocations configured
	// for this agent. May be empty when Prompt carries the full request.
	Skills []string `json:"skills,omitempty"`

	// Prompt, when non-empty, carries saved review instructions. When
	// Skills is non-empty it is appended after the selected skills; when
	// Skills is empty it is the full prompt for prompt-only review configs.
	Prompt string `json:"prompt,omitempty"`
}

// IsZero reports whether the config is effectively unset.
func (c ReviewConfig) IsZero() bool {
	return len(c.Skills) == 0 && c.Prompt == ""
}

// ReviewConfigFor returns the configured review config for the given agent.
// Returns a zero-value config when the agent has no entry; callers should
// check IsZero (or the individual fields) to decide whether configuration
// is present.
func (s *EntireSettings) ReviewConfigFor(agentName string) ReviewConfig {
	if s == nil {
		return ReviewConfig{}
	}
	return s.Review[agentName]
}

// InvestigateConfig holds the configuration for `entire investigate`.
// Unlike ReviewConfig, investigate runs the same shared prompt across
// all configured agents, so the schema is a flat agent list with global
// loop knobs rather than per-agent skill lists.
type InvestigateConfig struct {
	// Agents is the ordered list of agent names to round-robin during the loop.
	Agents []string `json:"agents,omitempty"`

	// MaxTurns is the per-agent turn budget. Defaults to 2 when zero
	// (see investigate.defaultMaxTurns).
	MaxTurns int `json:"max_turns,omitempty"`

	// Quorum is the count of `approve` stances needed to terminate the loop.
	// Zero means "all agents must approve" (matches marvin's default).
	Quorum int `json:"quorum,omitempty"`

	// AlwaysPrompt is appended to every turn's composed prompt, parallel
	// to ReviewConfig.Prompt.
	AlwaysPrompt string `json:"always_prompt,omitempty"`
}

// IsZero reports whether the config is effectively unset.
func (c *InvestigateConfig) IsZero() bool {
	if c == nil {
		return true
	}
	return len(c.Agents) == 0 && c.MaxTurns == 0 && c.Quorum == 0 && c.AlwaysPrompt == ""
}

// InvestigateConfig returns the configured investigate config. Returns nil
// when no configuration is present; callers should check IsZero (or guard
// for nil) to decide whether configuration is present.
func (s *EntireSettings) InvestigateConfig() *InvestigateConfig {
	if s == nil {
		return nil
	}
	return s.Investigate
}

// Load loads the Entire settings from .entire/settings.json, then applies
// clone-local preferences from the git common dir, then applies any overrides
// from .entire/settings.local.json if it exists.
// Returns default settings if no settings or preferences file exists.
// Works correctly from any subdirectory within the repository.
func Load(ctx context.Context) (*EntireSettings, error) {
	if worktreeRoot, ok := worktreeRootFromContext(ctx); ok {
		return loadForWorktreeRoot(ctx, worktreeRoot)
	}

	// Get absolute paths for settings files
	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
	if err != nil {
		settingsFileAbs = EntireSettingsFile // Fallback to relative
	}
	preferencesFileAbs := ""
	if path, prefErr := ClonePreferencesPath(ctx); prefErr == nil {
		preferencesFileAbs = path
	} else {
		// Log at Debug rather than silently dropping the preferences layer.
		// "Not in a git repo" is a legitimate case (some commands run outside
		// a repo), but a git PATH issue or .git/ permission failure is worth
		// finding via `ENTIRE_LOG_LEVEL=debug` when users report "my picker
		// choices vanished".
		logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
			slog.String("error", prefErr.Error()))
	}
	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
	if err != nil {
		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
	}

	return loadMergedSettings(settingsFileAbs, preferencesFileAbs, localSettingsFileAbs)
}

func loadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	settingsFileAbs := filepath.Join(worktreeRoot, EntireSettingsFile)
	preferencesFileAbs := ""
	if path, prefErr := clonePreferencesPathForWorktreeRoot(ctx, worktreeRoot); prefErr == nil {
		preferencesFileAbs = path
	} else {
		logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
			slog.String("error", prefErr.Error()))
	}
	localSettingsFileAbs := filepath.Join(worktreeRoot, EntireSettingsLocalFile)
	return loadMergedSettings(settingsFileAbs, preferencesFileAbs, localSettingsFileAbs)
}

func clonePreferencesPathForWorktreeRoot(ctx context.Context, worktreeRoot string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", worktreeRoot, "rev-parse", "--git-common-dir")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(worktreeRoot, commonDir)
	}
	return filepath.Join(filepath.Clean(commonDir), ClonePreferencesFile), nil
}

func loadMergedSettings(settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
	// Load base settings
	settings, err := loadFromFile(settingsFileAbs)
	if err != nil {
		return nil, fmt.Errorf("reading settings file: %w", err)
	}

	if preferencesFileAbs != "" {
		preferences, err := loadClonePreferencesFromFile(preferencesFileAbs)
		if err != nil {
			return nil, fmt.Errorf("reading clone preferences file: %w", err)
		}
		applyClonePreferences(settings, preferences)
	}

	// Apply local overrides if they exist
	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
	if err != nil {
		if !os.IsNotExist(err) {
			return nil, fmt.Errorf("reading local settings file: %w", err)
		}
		// Local file doesn't exist, continue without overrides
	} else {
		if err := mergeJSON(settings, localData); err != nil {
			return nil, fmt.Errorf("merging local settings: %w", err)
		}
	}

	// Re-validate after merge. Individual files are validated by loadFromFile,
	// but mergeJSON patches fields independently and can produce combinations
	// (e.g. model without provider when the local override sets only a model
	// on top of a base with no provider) that neither file alone contained.
	if err := settings.SummaryGeneration.Validate(); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	return settings, nil
}

// LoadFromFile loads settings from a specific file path without merging local overrides.
// Returns default settings if the file doesn't exist.
// Use this when you need to display individual settings files separately.
func LoadFromFile(filePath string) (*EntireSettings, error) {
	return loadFromFile(filePath)
}

// LoadProjectRaw reads .entire/settings.json as a generic JSON object so
// callers can inspect or mutate individual keys without losing unrelated
// fields to round-trip decoding.
//
// Returns:
//   - path: absolute path of the project settings file.
//   - raw: parsed JSON object, or an empty map when the file is missing.
//   - exists: false when the file does not exist (raw is empty); true otherwise.
//   - err: parse error or read error other than ENOENT.
//
// Pair with SaveProjectRaw for read-modify-write flows like the review-key
// migration. Owning the path resolution and raw IO here keeps callers from
// duplicating settings parsing in violation of the "Settings access must go
// through the settings package" rule in CLAUDE.md.
func LoadProjectRaw(ctx context.Context) (path string, raw map[string]json.RawMessage, exists bool, err error) {
	path, err = paths.AbsPath(ctx, EntireSettingsFile)
	if err != nil {
		path = EntireSettingsFile
	}
	data, readErr := os.ReadFile(path) //nolint:gosec // path is from AbsPath or a project-relative constant
	if readErr != nil {
		if os.IsNotExist(readErr) {
			return path, map[string]json.RawMessage{}, false, nil
		}
		return path, nil, false, fmt.Errorf("reading project settings: %w", readErr)
	}
	raw = map[string]json.RawMessage{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return path, nil, true, fmt.Errorf("parsing project settings: %w", err)
	}
	return path, raw, true, nil
}

// LoadLocalRaw reads .entire/settings.local.json as a generic JSON object,
// mirroring LoadProjectRaw for the per-developer overrides file. Returns
// exists=false (and an empty raw map) when the file does not exist — the
// common case for users who haven't created the local override file.
//
// Pair with the migration flow: callers can use this to detect when local
// overrides would mask a freshly-migrated setting, then warn the user
// before performing the migration.
func LoadLocalRaw(ctx context.Context) (path string, raw map[string]json.RawMessage, exists bool, err error) {
	path, err = paths.AbsPath(ctx, EntireSettingsLocalFile)
	if err != nil {
		path = EntireSettingsLocalFile
	}
	data, readErr := os.ReadFile(path) //nolint:gosec // path is from AbsPath or a project-relative constant
	if readErr != nil {
		if os.IsNotExist(readErr) {
			return path, map[string]json.RawMessage{}, false, nil
		}
		return path, nil, false, fmt.Errorf("reading local settings: %w", readErr)
	}
	raw = map[string]json.RawMessage{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return path, nil, true, fmt.Errorf("parsing local settings: %w", err)
	}
	return path, raw, true, nil
}

// SaveProjectRaw writes a generic JSON object back to .entire/settings.json
// atomically (temp file + rename). Callers should mutate the map returned by
// LoadProjectRaw and pass it back here so unrelated fields are preserved.
func SaveProjectRaw(path string, raw map[string]json.RawMessage) error {
	data, err := jsonutil.MarshalIndentWithNewline(raw, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal project settings: %w", err)
	}
	if err := jsonutil.WriteFileAtomic(path, data, 0o644); err != nil {
		return fmt.Errorf("writing project settings: %w", err)
	}
	return nil
}

// ClonePreferencesPath returns the clone-local preferences path in the git common dir.
func ClonePreferencesPath(ctx context.Context) (string, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}
	return filepath.Join(commonDir, ClonePreferencesFile), nil
}

// LoadClonePreferences loads clone-local preferences from the git common dir.
func LoadClonePreferences(ctx context.Context) (*ClonePreferences, error) {
	path, err := ClonePreferencesPath(ctx)
	if err != nil {
		return nil, err
	}
	return loadClonePreferencesFromFile(path)
}

// SaveClonePreferences saves clone-local preferences to the git common dir.
func SaveClonePreferences(ctx context.Context, prefs *ClonePreferences) error {
	path, err := ClonePreferencesPath(ctx)
	if err != nil {
		return err
	}
	return saveClonePreferencesToFile(prefs, path)
}

// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
// Use this when you have settings content from a non-file source (e.g., git show).
func LoadFromBytes(data []byte) (*EntireSettings, error) {
	s := &EntireSettings{Enabled: true}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(s); err != nil {
		return nil, fmt.Errorf("parsing settings: %w", err)
	}
	return s, nil
}

// loadFromFile loads settings from a specific file path.
// Returns default settings if the file doesn't exist.
func loadFromFile(filePath string) (*EntireSettings, error) {
	settings := &EntireSettings{
		Enabled: true, // Default to enabled
	}

	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
	if err != nil {
		if os.IsNotExist(err) {
			return settings, nil
		}
		return nil, fmt.Errorf("%w", err)
	}

	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(settings); err != nil {
		return nil, fmt.Errorf("parsing settings file: %w", err)
	}

	// Validate commit_linking if set
	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
	}

	// SummaryGeneration is NOT validated here — individual files may
	// legitimately contain only a model (provider comes from another file).
	// Validation happens after merge in Load().

	return settings, nil
}

func loadClonePreferencesFromFile(filePath string) (*ClonePreferences, error) {
	prefs := &ClonePreferences{}

	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
	if err != nil {
		if os.IsNotExist(err) {
			return prefs, nil
		}
		return nil, fmt.Errorf("%w", err)
	}

	// Lenient decoding here (vs. strict via DisallowUnknownFields in
	// loadFromFile for EntireSettings). Two reasons clone preferences need
	// the looser contract:
	//   1. They are rewritten on every picker save — a newer binary can
	//      introduce a field the older binary then sees as unknown, which
	//      under strict decoding would brick settings.Load for that older
	//      binary across the whole clone.
	//   2. The file lives in .git/, so users rarely hand-edit it; the
	//      typo-silently-ignored downside is theoretical here.
	// EntireSettings stays strict because it's committed and team-edited,
	// where unknown keys usually mean typos worth surfacing immediately.
	if err := json.Unmarshal(data, prefs); err != nil {
		return nil, fmt.Errorf("parsing preferences file: %w", err)
	}
	return prefs, nil
}

func saveClonePreferencesToFile(prefs *ClonePreferences, filePath string) error {
	if prefs == nil {
		prefs = &ClonePreferences{}
	}
	dir := filepath.Dir(filePath)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("creating preferences directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(prefs, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling preferences: %w", err)
	}

	if err := jsonutil.WriteFileAtomic(filePath, data, 0o644); err != nil {
		return fmt.Errorf("writing preferences file: %w", err)
	}
	return nil
}

func applyClonePreferences(settings *EntireSettings, prefs *ClonePreferences) {
	if prefs == nil {
		return
	}
	if prefs.Review != nil {
		settings.Review = prefs.Review
	}
	if prefs.ReviewFixAgent != "" {
		settings.ReviewFixAgent = prefs.ReviewFixAgent
	}
}

// mergeJSON merges JSON data into existing settings.
// Most fields only apply non-zero values from JSON. The review map is replaced
// whenever the key is present, so override files can clear or fully replace
// project-level review configuration.
func mergeJSON(settings *EntireSettings, data []byte) error {
	// Validate that there are no unknown keys using strict decoding.
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var temp EntireSettings
	if err := dec.Decode(&temp); err != nil {
		return fmt.Errorf("parsing JSON: %w", err)
	}

	// Parse into a map to check which fields are present.
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing JSON: %w", err)
	}

	if err := mergeScalarFields(settings, raw); err != nil {
		return err
	}
	if err := mergeStrategyOptions(settings, raw); err != nil {
		return err
	}
	if err := mergeSummaryGeneration(settings, raw); err != nil {
		return err
	}
	if err := mergeCommitLinking(settings, raw); err != nil {
		return err
	}
	if reviewRaw, ok := raw["review"]; ok {
		var review map[string]ReviewConfig
		if err := json.Unmarshal(reviewRaw, &review); err != nil {
			return fmt.Errorf("parsing review field: %w", err)
		}
		settings.Review = review
	}

	// Merge redaction sub-fields if present (field-level, not wholesale replace).
	if redactionRaw, ok := raw["redaction"]; ok {
		if settings.Redaction == nil {
			settings.Redaction = &RedactionSettings{}
		}
		if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
			return fmt.Errorf("parsing redaction field: %w", err)
		}
	}

	if err := mergeInvestigate(settings, raw); err != nil {
		return err
	}

	return nil
}

// mergeInvestigate replaces the investigate config from the override (whole-object
// replacement, parallel to how summary_generation is handled but simpler — the
// investigate schema is small and lacks per-field merge semantics).
func mergeInvestigate(settings *EntireSettings, raw map[string]json.RawMessage) error {
	investigateRaw, ok := raw["investigate"]
	if !ok {
		return nil
	}
	var cfg InvestigateConfig
	if err := unmarshalField("investigate", investigateRaw, &cfg); err != nil {
		return err
	}
	settings.Investigate = &cfg
	return nil
}

// mergeScalarFields merges simple bool, *bool, string, and int fields from raw JSON.
func mergeScalarFields(settings *EntireSettings, raw map[string]json.RawMessage) error {
	if err := mergeRawBool(raw, "enabled", &settings.Enabled); err != nil {
		return err
	}
	if err := mergeRawBool(raw, "local_dev", &settings.LocalDev); err != nil {
		return err
	}
	if err := mergeRawBool(raw, "absolute_git_hook_path", &settings.AbsoluteGitHookPath); err != nil {
		return err
	}
	if err := mergeRawBool(raw, "external_agents", &settings.ExternalAgents); err != nil {
		return err
	}
	if err := mergeRawBool(raw, "vercel", &settings.Vercel); err != nil {
		return err
	}
	if err := mergeRawBoolPtr(raw, "telemetry", &settings.Telemetry); err != nil {
		return err
	}
	if err := mergeRawBoolPtr(raw, "sign_checkpoint_commits", &settings.SignCheckpointCommits); err != nil {
		return err
	}
	if err := mergeRawStringNonEmpty(raw, "log_level", &settings.LogLevel); err != nil {
		return err
	}
	if err := mergeRawStringNonEmpty(raw, "review_fix_agent", &settings.ReviewFixAgent); err != nil {
		return err
	}
	if err := mergeRawInt(raw, "summary_timeout_seconds", &settings.SummaryTimeoutSeconds); err != nil {
		return err
	}
	return nil
}

func mergeRawBool(raw map[string]json.RawMessage, key string, dst *bool) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	return unmarshalField(key, v, dst)
}

func mergeRawBoolPtr(raw map[string]json.RawMessage, key string, dst **bool) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	var b bool
	if err := unmarshalField(key, v, &b); err != nil {
		return err
	}
	*dst = &b
	return nil
}

func mergeRawStringNonEmpty(raw map[string]json.RawMessage, key string, dst *string) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	var s string
	if err := unmarshalField(key, v, &s); err != nil {
		return err
	}
	if s != "" {
		*dst = s
	}
	return nil
}

func mergeRawInt(raw map[string]json.RawMessage, key string, dst *int) error {
	v, ok := raw[key]
	if !ok {
		return nil
	}
	return unmarshalField(key, v, dst)
}

func unmarshalField(key string, data json.RawMessage, dst any) error {
	if err := json.Unmarshal(data, dst); err != nil {
		return fmt.Errorf("parsing %s field: %w", key, err)
	}
	return nil
}

func mergeStrategyOptions(settings *EntireSettings, raw map[string]json.RawMessage) error {
	optionsRaw, ok := raw["strategy_options"]
	if !ok {
		return nil
	}
	var opts map[string]any
	if err := unmarshalField("strategy_options", optionsRaw, &opts); err != nil {
		return err
	}
	if settings.StrategyOptions == nil {
		settings.StrategyOptions = opts
	} else {
		for k, v := range opts {
			settings.StrategyOptions[k] = v
		}
	}
	return nil
}

func mergeSummaryGeneration(settings *EntireSettings, raw map[string]json.RawMessage) error {
	summaryRaw, ok := raw["summary_generation"]
	if !ok {
		return nil
	}
	if settings.SummaryGeneration == nil {
		settings.SummaryGeneration = &SummaryGenerationSettings{}
	}

	var summaryFields map[string]json.RawMessage
	if err := unmarshalField("summary_generation", summaryRaw, &summaryFields); err != nil {
		return err
	}

	_, modelInOverride := summaryFields["model"]

	if providerRaw, ok := summaryFields["provider"]; ok {
		var provider string
		if err := unmarshalField("summary_generation.provider", providerRaw, &provider); err != nil {
			return err
		}
		// If the override switches providers without also setting a model,
		// the base's model was tuned to the old provider and would likely
		// cause a runtime failure when handed to the new one (e.g. codex
		// rejecting "sonnet"). Clear it so the new provider falls back to
		// its own default.
		if provider != settings.SummaryGeneration.Provider && !modelInOverride {
			settings.SummaryGeneration.Model = ""
		}
		settings.SummaryGeneration.Provider = provider
	}

	if modelRaw, ok := summaryFields["model"]; ok {
		var model string
		if err := unmarshalField("summary_generation.model", modelRaw, &model); err != nil {
			return err
		}
		settings.SummaryGeneration.Model = model
	}
	return nil
}

func mergeCommitLinking(settings *EntireSettings, raw map[string]json.RawMessage) error {
	commitLinkingRaw, ok := raw["commit_linking"]
	if !ok {
		return nil
	}
	var cl string
	if err := unmarshalField("commit_linking", commitLinkingRaw, &cl); err != nil {
		return err
	}
	if cl == "" {
		return nil
	}
	switch cl {
	case CommitLinkingAlways, CommitLinkingPrompt:
		settings.CommitLinking = cl
	default:
		return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
	}
	return nil
}

// mergeRedaction merges redaction overrides into existing RedactionSettings.
// Only fields present in the override JSON are applied.
func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing redaction: %w", err)
	}
	if piiRaw, ok := raw["pii"]; ok {
		if dst.PII == nil {
			dst.PII = &PIISettings{}
		}
		if err := mergePIISettings(dst.PII, piiRaw); err != nil {
			return err
		}
	}
	if csRaw, ok := raw["custom_redactions"]; ok {
		var cs map[string]string
		if err := json.Unmarshal(csRaw, &cs); err != nil {
			return fmt.Errorf("parsing redaction.custom_redactions: %w", err)
		}
		if dst.CustomRedactions == nil {
			dst.CustomRedactions = cs
		} else {
			for k, v := range cs {
				dst.CustomRedactions[k] = v
			}
		}
	}
	return nil
}

// mergePIISettings merges PII overrides into existing PIISettings.
// Only fields present in the override JSON are applied; missing fields
// are preserved from the base settings.
func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing pii: %w", err)
	}
	if v, ok := raw["enabled"]; ok {
		if err := json.Unmarshal(v, &dst.Enabled); err != nil {
			return fmt.Errorf("parsing pii.enabled: %w", err)
		}
	}
	if v, ok := raw["email"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.email: %w", err)
		}
		dst.Email = &b
	}
	if v, ok := raw["phone"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.phone: %w", err)
		}
		dst.Phone = &b
	}
	if v, ok := raw["address"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.address: %w", err)
		}
		dst.Address = &b
	}
	if v, ok := raw["custom_patterns"]; ok {
		var cp map[string]string
		if err := json.Unmarshal(v, &cp); err != nil {
			return fmt.Errorf("parsing pii.custom_patterns: %w", err)
		}
		if dst.CustomPatterns == nil {
			dst.CustomPatterns = cp
		} else {
			for k, val := range cp {
				dst.CustomPatterns[k] = val
			}
		}
	}
	return nil
}

// IsSetUp returns true if Entire has been set up in the current repository.
// This checks if .entire/settings.json exists.
// Use this to avoid creating files/directories in repos where Entire was never enabled.
func IsSetUp(ctx context.Context) bool {
	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
	if err != nil {
		return false
	}
	_, err = os.Stat(settingsFileAbs)
	return err == nil
}

// IsSetUpAny returns true if Entire has been set up in the current repository,
// checking both .entire/settings.json and .entire/settings.local.json.
// Use this to detect any prior setup, even if only local settings exist.
func IsSetUpAny(ctx context.Context) bool {
	if IsSetUp(ctx) {
		return true
	}
	localFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
	if err != nil {
		return false
	}
	_, err = os.Lstat(localFileAbs)
	return err == nil
}

// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
// This checks if .entire/settings.json exists AND has enabled: true.
// Use this for hooks that should be no-ops when Entire is not active.
func IsSetUpAndEnabled(ctx context.Context) bool {
	if !IsSetUp(ctx) {
		return false
	}
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.Enabled
}

// MirrorsToV1CustomRef reports whether the v1 custom-ref mirror is opted in.
// Returns false if settings cannot be loaded.
func MirrorsToV1CustomRef(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.MirrorsToV1CustomRef()
}

// IsFilteredFetchesEnabled checks if filtered fetches should be used.
// When enabled, filtered fetches always resolve remote names to URLs first so
// git does not persist promisor settings onto named remotes in local config.
// Returns false by default.
func IsFilteredFetchesEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.IsFilteredFetchesEnabled()
}

// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsSummarizeEnabled(ctx context.Context) bool {
	settings, err := Load(ctx)
	if err != nil {
		return false
	}
	return settings.IsSummarizeEnabled()
}

// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
func (s *EntireSettings) IsSummarizeEnabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
	if !ok {
		return false
	}
	enabled, ok := summarizeOpts["enabled"].(bool)
	if !ok {
		return false
	}
	return enabled
}

// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
type CheckpointRemoteConfig struct {
	Provider string // e.g., "github"
	Repo     string // e.g., "org/checkpoints-repo"
}

// Owner returns the owner portion of the repo field (before the slash).
// Returns empty string if the repo field doesn't contain a slash.
func (c *CheckpointRemoteConfig) Owner() string {
	parts := strings.SplitN(c.Repo, "/", 2)
	if len(parts) < 2 {
		return ""
	}
	return parts[0]
}

// GetCheckpointRemote returns the configured checkpoint remote.
// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
// Returns nil if not configured, wrong type, or missing required fields.
func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
	if s.StrategyOptions == nil {
		return nil
	}
	val, ok := s.StrategyOptions["checkpoint_remote"]
	if !ok {
		return nil
	}
	m, ok := val.(map[string]any)
	if !ok {
		return nil
	}
	provider, providerOK := m["provider"].(string)
	repo, repoOK := m["repo"].(string)
	if !providerOK || !repoOK || provider == "" || repo == "" {
		return nil
	}
	if !strings.Contains(repo, "/") {
		return nil
	}
	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
}

// MirrorsToV1CustomRef reports whether checkpoints_version opts into mirroring
// committed metadata to the v1 custom ref (refs/entire/checkpoints/v1.1). v1
// remains the source of truth; the v1 custom ref is a local-only mirror.
// Returns false when unset or set to any other value.
func (s *EntireSettings) MirrorsToV1CustomRef() bool {
	if s.StrategyOptions == nil {
		return false
	}
	return isV1CustomRefValue(s.StrategyOptions["checkpoints_version"])
}

// isV1CustomRefValue reports whether a checkpoints_version value selects the v1
// custom ref. Only the JSON string "1.1" opts in; numeric values remain plain v1.
func isV1CustomRefValue(val any) bool {
	s, ok := val.(string)
	return ok && s == "1.1"
}

// IsFilteredFetchesEnabled checks if fetches should use --filter=blob:none.
// When enabled, filtered fetches always use resolved URLs rather than remote
// names to avoid persisting promisor settings onto named remotes.
func (s *EntireSettings) IsFilteredFetchesEnabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	val, ok := s.StrategyOptions["filtered_fetches"].(bool)
	return ok && val
}

// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
// Returns true if push_sessions is explicitly set to false.
func (s *EntireSettings) IsPushSessionsDisabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	val, exists := s.StrategyOptions["push_sessions"]
	if !exists {
		return false
	}
	if boolVal, ok := val.(bool); ok {
		return !boolVal // disabled = !push_sessions
	}
	return false
}

// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
// Returns false by default if settings cannot be loaded or the key is missing.
func IsExternalAgentsEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.ExternalAgents
}

// IsSignCheckpointCommitsEnabled returns true if checkpoint commits should be signed.
// Defaults to true when the setting is not explicitly set.
func (s *EntireSettings) IsSignCheckpointCommitsEnabled() bool {
	return s.SignCheckpointCommits == nil || *s.SignCheckpointCommits
}

// IsSignCheckpointCommitsEnabled checks if checkpoint commit signing is enabled in settings.
// Returns true by default if settings cannot be loaded or the key is missing.
func IsSignCheckpointCommitsEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return true
	}
	return s.IsSignCheckpointCommitsEnabled()
}

// Save saves the settings to .entire/settings.json.
func Save(ctx context.Context, settings *EntireSettings) error {
	return saveToFile(ctx, settings, EntireSettingsFile)
}

// SaveLocal saves the settings to .entire/settings.local.json.
func SaveLocal(ctx context.Context, settings *EntireSettings) error {
	return saveToFile(ctx, settings, EntireSettingsLocalFile)
}

// saveToFile saves settings to the specified file path.
func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
	// Get absolute path for the file
	filePathAbs, err := paths.AbsPath(ctx, filePath)
	if err != nil {
		filePathAbs = filePath // Fallback to relative
	}

	// Ensure directory exists
	dir := filepath.Dir(filePathAbs)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("creating settings directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling settings: %w", err)
	}

	if err := jsonutil.WriteFileAtomic(filePathAbs, data, 0o644); err != nil {
		return fmt.Errorf("writing settings file: %w", err)
	}
	return nil
}

package cli

import (
	"fmt"
	"io"

	"github.com/spf13/cobra"
)

// newPluginGroupCmd builds `entire plugin` and its subcommands. The kubectl
// dispatcher in plugin.go is the runtime mechanism — these commands manage a
// per-user managed directory that the dispatcher discovers because main.go
// prepends it to PATH at startup.
//
// Currently only local symlink installs are supported. GitHub-release
// asset and git-clone install paths are deferred until there's demand.
func newPluginGroupCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "plugin",
		Short: "Manage Entire plugins (install, list, remove)",
		Long: `Manage Entire plugins.

Plugins are external executables named 'entire-<name>'. The CLI discovers
plugins on $PATH and from a per-user managed directory which is
auto-prepended to PATH at startup. The managed directory is, in order of
precedence:

  $ENTIRE_PLUGIN_DIR/bin (override)
  $XDG_DATA_HOME/entire/plugins/bin (Linux/macOS, when set)
  ~/.local/share/entire/plugins/bin (Linux/macOS default)
  %LOCALAPPDATA%\entire\plugins\bin (Windows, when set)
  ~\AppData\Local\entire\plugins\bin (Windows fallback when LOCALAPPDATA is unset)

Commands:
  install   Install a plugin by linking or copying an existing executable
  list      List plugins installed in the managed directory
  remove    Remove a plugin from the managed directory

Examples:
  entire plugin install ./dist/entire-pgr
  entire plugin list
  entire plugin remove pgr`,
	}

	cmd.AddCommand(newPluginInstallCmd())
	cmd.AddCommand(newPluginListCmd())
	cmd.AddCommand(newPluginRemoveCmd())
	return cmd
}

func newPluginInstallCmd() *cobra.Command {
	var force bool
	cmd := &cobra.Command{
		Use:   "install <path>",
		Short: "Link or copy a plugin executable into the managed directory",
		Long: `Link or copy a plugin executable into the managed directory.

The source must be a file whose basename starts with 'entire-' (the
dispatcher only resolves names of that shape). On Unix the file must be
executable.

The CLI prefers a symlink so rebuilds of the source are reflected
immediately, and falls back to a hardlink, then a copy, if symlinks aren't
available (notably Windows without Developer Mode).

After install, 'entire <name>' invokes the plugin via the kubectl-style
dispatcher — the managed directory is auto-prepended to $PATH.

Examples:
  entire plugin install ./dist/entire-pgr
  entire plugin install /usr/local/bin/entire-pgr --force`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			p, err := InstallPluginFromPath(InstallPluginOptions{
				SourcePath: args[0],
				Force:      force,
			})
			if err != nil {
				return fmt.Errorf("install plugin: %w", err)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Installed plugin %q → %s\n", p.Name, p.Path)
			warnIfShadowsBuiltin(cmd, p.Name)
			return nil
		},
	}
	cmd.Flags().BoolVar(&force, "force", false, "Replace an existing entry with the same name")
	return cmd
}

// warnIfShadowsBuiltin prints a one-line note to stderr when the just-installed
// plugin name matches a built-in command. The dispatcher's resolvePlugin gates
// dispatch on rootCmd.Find, so the built-in always wins at runtime — without
// this hint, a user who installed a shadowed plugin would silently get the
// built-in and have no idea their install was inert. We mirror the dispatcher's
// help/completion priming so names like "help" surface the warning too.
func warnIfShadowsBuiltin(cmd *cobra.Command, name string) {
	root := cmd.Root()
	if root == nil {
		return
	}
	root.InitDefaultHelpCmd()
	root.InitDefaultCompletionCmd(name)
	if c, _, err := root.Find([]string{name}); err == nil && c != root {
		fmt.Fprintf(cmd.ErrOrStderr(), "Note: %q shadows the built-in command; the built-in will take precedence at runtime.\n", name)
	}
}

func newPluginListCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "list",
		Short: "List plugins installed in the managed directory",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runPluginList(cmd.OutOrStdout())
		},
	}
}

func runPluginList(w io.Writer) error {
	plugins, err := ListInstalledPlugins()
	if err != nil {
		return fmt.Errorf("list plugins: %w", err)
	}
	dir, err := PluginBinDir()
	if err != nil {
		return fmt.Errorf("plugin bin dir: %w", err)
	}
	if len(plugins) == 0 {
		fmt.Fprintf(w, "No plugins installed in %s.\n", dir)
		fmt.Fprintln(w, "Install one with 'entire plugin install <path>', or drop an entire-<name> binary anywhere on $PATH.")
		return nil
	}
	fmt.Fprintf(w, "Managed plugin directory: %s\n\n", dir)
	for _, p := range plugins {
		if p.Symlink {
			fmt.Fprintf(w, "  %-20s → %s\n", p.Name, p.LinkTarget)
		} else {
			fmt.Fprintf(w, "  %-20s %s\n", p.Name, p.Path)
		}
	}
	return nil
}

func newPluginRemoveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "remove <name>",
		Short: "Remove a plugin from the managed directory",
		Long: `Remove a plugin from the managed directory.

Only entries in the managed directory are affected. Plugins installed by
dropping a binary elsewhere on $PATH are unmanaged — remove those by hand.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := RemoveInstalledPlugin(args[0]); err != nil {
				return fmt.Errorf("remove plugin: %w", err)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Removed plugin %q\n", args[0])
			return nil
		},
	}
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/telemetry"
	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/spf13/cobra"
)

// External-command resolution, kubectl-style. When the user invokes
// `entire <name>` and <name> isn't a built-in subcommand, look for an
// `entire-<name>` binary on PATH and exec it with the remaining args.
// Stdio and exit codes pass through. Binaries matching the agent
// protocol prefix are reserved for the external agent registry and
// skipped here.
const (
	pluginBinaryPrefix      = "entire-"
	agentPluginBinaryPrefix = "entire-agent-"
)

// MaybeRunPlugin returns (true, exitCode) when an external command was
// resolved and run. On launch failure (e.g. missing executable bit)
// returns (true, 1) after printing to stderr. On no-match returns
// (false, 0) so the caller can fall through to Cobra.
//
// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
// behavior for built-ins: both fire only on a successful (exit-0) run.
func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int) {
	binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
	if !ok {
		return false, 0
	}
	pluginName := args[0]
	exitCode = runPlugin(ctx, pluginName, binPath, pluginArgs)
	if exitCode == 0 {
		maybeTrackPluginInvocation(ctx, pluginName)
		versioncheck.CheckAndNotify(ctx, os.Stdout, versioninfo.Version)
	}
	return true, exitCode
}

// maybeTrackPluginInvocation fires telemetry only for plugins on the
// official allowlist. Third-party plugin names are never sent — see
// IsOfficialPlugin for the rationale.
func maybeTrackPluginInvocation(ctx context.Context, pluginName string) {
	if !IsOfficialPlugin(pluginName) {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil {
		return
	}
	if s.Telemetry == nil || !*s.Telemetry {
		return
	}
	telemetry.TrackPluginDetached(pluginName, s.Enabled, versioninfo.Version)
}

func resolvePlugin(rootCmd *cobra.Command, args []string) (binPath string, pluginArgs []string, ok bool) {
	if len(args) == 0 {
		return "", nil, false
	}
	name := args[0]
	if !isPluginCandidate(name) {
		return "", nil, false
	}
	// Cobra adds `help` and `completion` to the command tree inside Execute,
	// not in the constructor / SetHelpCommand. Without priming them, Find
	// reports "unknown command" for those names and an entire-help (or
	// entire-completion) binary on PATH would shadow the built-in. Both
	// initializers are idempotent and Execute calls them again later.
	rootCmd.InitDefaultHelpCmd()
	rootCmd.InitDefaultCompletionCmd(args...)
	// Built-in commands always win.
	if cmd, _, err := rootCmd.Find(args); err == nil && cmd != rootCmd {
		return "", nil, false
	}
	binName := pluginBinaryPrefix + name
	binPath, err := exec.LookPath(binName)
	if err != nil {
		// LookPath conflates "not on PATH" with "found but not executable".
		// Distinguish: if a file with this name exists on PATH but isn't
		// executable, surface that as a launch error rather than falling
		// through to Cobra's generic unknown-command path.
		if p, found := findInaccessiblePlugin(binName); found {
			return p, args[1:], true
		}
		return "", nil, false
	}
	if isAgentProtocolBinary(binPath) {
		return "", nil, false
	}
	return binPath, args[1:], true
}

// findInaccessiblePlugin scans PATH for a non-directory file with the
// given name. Only meaningful after exec.LookPath has already failed —
// indicates the file exists but lacks the executable bit (or the
// equivalent platform-specific accessibility).
func findInaccessiblePlugin(filename string) (string, bool) {
	for _, dir := range filepath.SplitList(os.Getenv("PATH")) {
		if dir == "" {
			continue
		}
		candidate := filepath.Join(dir, filename)
		info, err := os.Stat(candidate) //nolint:gosec // PATH entries are user-trusted; scanning them is the point.
		if err != nil || info.IsDir() {
			continue
		}
		return candidate, true
	}
	return "", false
}

// isPluginCandidate reports whether name is a syntactically valid plugin
// name the dispatcher should attempt to resolve. It is a thin bool wrapper
// over validatePluginName so the dispatcher's gate and the managed store's
// install-time check can never drift.
func isPluginCandidate(name string) bool {
	return validatePluginName(name) == nil
}

// isAgentProtocolBinary returns true when the binary name is reserved for
// the external agent protocol. Strip Windows extensions first so
// `entire-agent-foo.exe` is also recognized.
func isAgentProtocolBinary(binPath string) bool {
	base := external.StripExeExt(filepath.Base(binPath))
	return strings.HasPrefix(base, agentPluginBinaryPrefix)
}

// runPlugin executes the resolved plugin binary, propagating its exit code.
// On context cancellation the child gets SIGINT (with a 5s grace before the
// runtime falls back to SIGKILL) so plugins can clean up. Terminal signals
// reach the child directly via the shared process group.
func runPlugin(ctx context.Context, pluginName, binPath string, args []string) int {
	cmd := exec.CommandContext(ctx, binPath, args...)
	cmd.Cancel = func() error { return cmd.Process.Signal(os.Interrupt) }
	cmd.WaitDelay = 5 * time.Second
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	extras := []string{"ENTIRE_CLI_VERSION=" + versioninfo.Version}
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
		extras = append(extras, "ENTIRE_REPO_ROOT="+repoRoot)
	}
	// Per-plugin durable storage. Passed regardless of where the binary lives
	// so plugins installed via raw PATH and via `entire plugin install` get
	// the same contract. The dir is not pre-created — that's the plugin's
	// responsibility on first use.
	//
	// PluginDataDir can only fail in degenerate environments (no resolvable
	// home dir, or a relative ENTIRE_PLUGIN_DIR override). The plugin name
	// itself already passed isPluginCandidate in resolvePlugin, so the name
	// validator branch can't fire here. Proceed without the var rather than
	// refuse to launch: a misconfigured environment is the user's problem to
	// surface, not a reason to break plugins that don't read the var. The
	// failure is logged at debug rather than printed to stderr — printing
	// would noise every plugin invocation in a degenerate env.
	parentEnv := os.Environ()
	if dataDir, err := PluginDataDir(pluginName); err == nil {
		extras = append(extras, pluginEnvPluginData+"="+dataDir)
	} else {
		// Strip any inherited value so the plugin doesn't silently see a
		// value we never sanctioned. Without this strip, a user with
		// ENTIRE_PLUGIN_DATA_DIR pre-set in their shell would have that
		// value pass through (ENTIRE_* is in the pluginEnv allowlist
		// prefix), even though resolution here failed.
		parentEnv = removeEnvKey(parentEnv, pluginEnvPluginData)
		logging.Debug(ctx, "ENTIRE_PLUGIN_DATA_DIR unset for plugin",
			slog.String("plugin", pluginName),
			slog.String("error", err.Error()))
	}
	cmd.Env = pluginEnv(parentEnv, extras...)

	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return exitErr.ExitCode()
		}
		// Prefix with the plugin name so users can tell parent vs child
		// errors apart in mixed stderr.
		fmt.Fprintf(os.Stderr, "Failed to run plugin %s: %v\n", filepath.Base(binPath), err)
		return 1
	}
	return 0
}

