	}))
	defer srv.Close()

	meta := &PluginMetadata{DownloadURL: srv.URL + "/dl/{asset}"}
	fa, err := downloadPluginAsset(context.Background(), meta, "https://example.invalid/entire-run", "run", "v1.0.0", t.TempDir())
