13	// Dependency handling is install-time only. Dispatch stays zero-cost: a
14	// plugin invokes its deps as entire-<dep> via PATH at runtime (the managed
15	// bin dir is prepended for plugin children), and `entire plugin doctor`
16	// reports drift after the fact. There is deliberately no version-range
17	// solver — requirements carry at most a minimum version.
18	
19	// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
20	// practice; the bound turns a metadata cycle that slips past the visited
21	// set (e.g. two names aliasing one repo) into an error instead of a hang.
22	const maxDepDepth = 10
23	
24	// DepAction is one planned dependency install or upgrade.
25	type DepAction struct {
26		Name       string
27		RepoURL    string
28		MinVersion string
29		// Upgrade is true when the dependency is installed but below
30		// MinVersion; the action reinstalls at the latest tag.
31		Upgrade bool
32		// CurrentTag is the installed tag for upgrades.
33		CurrentTag string
34		// FromIndex is true when the repo URL came from the index (trusted)
35		// rather than from another plugin's metadata.
36		FromIndex bool
37	}
38	
39	// DepPlan is the result of resolving a plugin's transitive requirements.
40	type DepPlan struct {
41		Actions []DepAction
42		// Warnings are non-blocking observations, e.g. a dependency satisfied
43		// from raw $PATH whose version cannot be verified.
44		Warnings []string
45	}
46	
47	// PlanDependencyInstalls resolves the transitive requirements of rootReqs
48	// into ordered install/upgrade actions. Missing dependencies must be
49	// resolvable to a repo URL via the requirement itself or the index. The
50	// visited set plus a depth bound make cycles an error path, not a hang.
51	func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
52		plan := &DepPlan{}
53		visited := map[string]bool{}
54		if err := planDeps(ctx, rootReqs, idx, plan, visited, 0); err != nil {
55			return nil, err
56		}
57		return plan, nil
58	}
59	
60	func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, visited map[string]bool, depth int) error {
61		if depth > maxDepDepth {
62			return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
63		}
64		for _, req := range reqs {
65			if visited[req.Name] {
66				continue
67			}
68			visited[req.Name] = true
69	
70			satisfied, warning, err := dependencySatisfied(req)
71			if err != nil {
72				return err
73			}
74			if warning != "" {
75				plan.Warnings = append(plan.Warnings, warning)
76			}
77			if satisfied {
78				continue
79			}
80	
81			m, err := LoadPluginManifest(req.Name)
82			if err != nil {
83				return err
84			}
85			action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
86			if m != nil {
87				// Installed but below min_version: upgrade in place from its
88				// recorded repo.
89				action.Upgrade = true
90				action.CurrentTag = m.Tag
91				action.RepoURL = m.RepoURL
92			} else {
93				action.RepoURL = req.RepoURL
94				if action.RepoURL == "" {
95					if e := idx.Find(req.Name); e != nil {
96						action.RepoURL = e.RepoURL
97						action.FromIndex = true
98					}
99				} else if idx.HasRepoURL(action.RepoURL) {
100					action.FromIndex = true
101				}
102				if action.RepoURL == "" {
103					return fmt.Errorf("dependency %q is not installed and has no repo URL (not in the plugin index either); add repo_url to the requirement or install it manually", req.Name)
104				}
105			}
106			plan.Actions = append(plan.Actions, action)
107	
108			// Recurse into what the dependency itself requires, using metadata
109			// only — nothing is downloaded during planning.
110			tag := ""
111			if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
112				tag = tags[0]
113			}
114			if tag == "" {
115				continue // install will fail with a clearer error later
116			}
117			meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
118			if err != nil || meta == nil {
119				continue
120			}
121			if err := planDeps(ctx, meta.Requires, idx, plan, visited, depth+1); err != nil {
122				return err
123			}
124		}
125		return nil
126	}
127	
128	// dependencySatisfied checks whether a requirement is already met, in
129	// order: managed install with manifest (version-checkable) → managed entry
130	// without manifest (local-dev, version unknown) → raw $PATH (version
131	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
132	// (main.go restores it for built-ins), so LookPath here sees only
133	// raw-PATH plugins — managed entries are checked explicitly first.
134	func dependencySatisfied(req PluginRequirement) (satisfied bool, warning string, err error) {
135		m, err := LoadPluginManifest(req.Name)
136		if err != nil {
137			return false, "", err
138		}
139		if m != nil {
140			if req.MinVersion == "" || semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0 {
141				return true, "", nil
142			}
143			return false, "", nil // triggers the upgrade path in planDeps
144		}
145		installed, err := FindInstalledPlugin(req.Name)
146		if err != nil {
147			return false, "", err
148		}
149		if installed != nil {
150			return true, unverifiableVersionWarning(req, "a local-dev install"), nil
151		}
152		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
153			return true, unverifiableVersionWarning(req, "$PATH"), nil
154		}
155		return false, "", nil
156	}
157	
158	func unverifiableVersionWarning(req PluginRequirement, source string) string {
159		if req.MinVersion == "" {
160			return ""
161		}
162		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
163	}
164	
165	// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
166	func ExecuteDepPlan(ctx context.Context, plan *DepPlan) error {
167		for _, a := range plan.Actions {
168			if _, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{RepoURL: a.RepoURL, Force: a.Upgrade}); err != nil {
169				return fmt.Errorf("install dependency %q: %w", a.Name, err)
170			}
171		}
172		return nil
173	}
174	
175	// DependentsOf returns the names of managed plugins whose manifests list
176	// name as a requirement — the remove guard. Computed by scanning
177	// pkg/*/manifest.yml; no extra state to maintain.
178	func DependentsOf(name string) ([]string, error) {
179		manifests, err := ListPluginManifests()
180		if err != nil {
181			return nil, err
182		}
183		var out []string
184		for _, m := range manifests {
