186				if req.Name == name {
187					out = append(out, m.Name)
188					break
189				}
190			}
191		}
192		return out, nil
193	}
194	
195	// PluginDoctorIssue is one problem found by RunPluginDoctor.
196	type PluginDoctorIssue struct {
197		Plugin  string
