93	func TestSyncPluginIndex_OfflineUsesStaleCopy(t *testing.T) { //nolint:paralleltest // mutates env via cache isolation
94		t.Setenv("XDG_CACHE_HOME", t.TempDir())
95		url, dir := newIndexRepo(t, `{"version":1,"plugins":[{"name":"run","repo_url":"https://x.example/entire-run"}]}`)
96		ctx := context.Background()
97		if _, err := SyncPluginIndex(ctx, url, false); err != nil {
98			t.Fatalf("initial sync: %v", err)
99		}
100		// Simulate the remote disappearing (laptop offline / index moved).
101		if out, err := exec.CommandContext(t.Context(), "rm", "-rf", dir).CombinedOutput(); err != nil {
102			t.Fatalf("rm: %v: %s", err, out)
103		}
104		idx, err := SyncPluginIndex(ctx, url, true) // force → refresh fails → stale copy
105		if err != nil {
106			t.Fatalf("offline sync should fall back to cache: %v", err)
107		}
108		if len(idx.Plugins) != 1 {
109			t.Errorf("stale copy plugins = %d, want 1", len(idx.Plugins))
110		}
111	}
